function validate([image]) {
  if (!Array.isArray(image) || image.length < 1 || image.length > 20) return 'image needs 1 to 20 rows.';
  const n = image.length;
  for (const row of image) {
    if (!Array.isArray(row) || row.length !== n) return 'image must be square: every row has n values.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Every pixel is 0 or 1.';
  }
  return null;
}

