function flipAndInvertImage(image) {
  const result = [];
  for (const row of image) {
    const mirrored = [];
    for (let j = row.length - 1; j >= 0; j--) mirrored.push(row[j] === 1 ? 0 : 1);
    result.push(mirrored);
  }
  return result;
}

