function generate(rand, size) {
  const n = size === 'small' ? 1 + Math.floor(rand() * 5) : 18 + Math.floor(rand() * 3);
  const ones = rand();
  const image = Array.from({ length: n }, () => Array.from({ length: n }, () => (rand() < ones ? 1 : 0)));
